import {
  Button,
  Checkbox,
  cn,
  EmptyState,
  Label,
  ToggleGroup,
  ToggleGroupItem,
} from 'platform-bible-react';
import { Lock, X } from 'lucide-react';
import { ReactNode, useId } from 'react';
import { formatReplacementString } from 'platform-bible-utils';
import {
  RESOURCE_COLLECTION_OPTIONS_KEYS,
  isResourceCollectionViewMode,
  type ResourceCollectionOptionsLocalizedStrings,
  type ResourceCollectionOptionsProps,
  type ResourceCollectionOptionsStringKey,
  type ViewOptionsTextEntry,
} from './resource-collection-options.types';

export {
  RESOURCE_COLLECTION_OPTIONS_KEYS,
  RESOURCE_COLLECTION_OPTIONS_STRING_KEYS,
  RESOURCE_COLLECTION_VIEW_MODES,
  isResourceCollectionViewMode,
  type ResourceCollectionOptionsStringKey,
  type ResourceCollectionOptionsLocalizedStrings,
  type ResourceCollectionOptionsProps,
  type ResourceCollectionViewMode,
  type ViewOptionsTextEntry,
} from './resource-collection-options.types';

const localize = (
  strings: ResourceCollectionOptionsLocalizedStrings,
  key: ResourceCollectionOptionsStringKey,
) => strings[key] ?? key;

/**
 * Reusable, presentational View Options inner component: a VIEW toggle (Verse / Chapter), a TEXTS
 * list (admin-shared top section + user bottom section, headed "Team resources" and "User
 * resources" when there are admin-shared rows and `isGrouped` is on), and a Get Resources button.
 * It holds no PAPI/popover/persistence state — callers pass the computed rows and callbacks — so
 * the same component renders inside the Scripture Text Grid popover and inside a resource-sharing
 * dialog.
 *
 * Chapter is disabled with a "not yet available" hint unless `isChapterEnabled` is set. The hover-✕
 * renders only on rows with `isUserRemovable === true`.
 *
 * Per UX: admin-chosen resources always stay visible in the top grouping of View Options — a user
 * can never remove them from the list (so admin rows get no remove-✕ control). But a user may still
 * hide an admin resource from the grid (e.g. to save space) by unchecking it, so admin rows keep
 * their checkbox.
 */
export function ResourceCollectionOptions({
  viewMode,
  onViewModeChange,
  isChapterEnabled = false,
  top,
  bottom,
  isGrouped = true,
  installingResourceNames = [],
  onCheckedChange,
  onRemoveFromList,
  onGetResources,
  disabled = false,
  disabledMessage,
  localizedStrings = {},
}: ResourceCollectionOptionsProps) {
  const headingIdPrefix = useId();
  const teamHeadingId = `${headingIdPrefix}-team`;
  const userHeadingId = `${headingIdPrefix}-user`;
  const removeHintId = `${headingIdPrefix}-remove-hint`;
  // A group's heading shows only over rows. Installing rows belong with the user's own, so they
  // alone are enough for its heading.
  const hasTeamRows = top.length > 0;
  const hasUserRows = bottom.length > 0 || installingResourceNames.length > 0;
  // The ✕ removes from the list every tab reads, which the row alone cannot say; the checkbox is
  // how to hide a text from this grid only.
  const hasRemoveHint = !disabled && bottom.some((row) => row.isUserRemovable);

  // Shown only when interactive (`!disabled`): while disabled we show `disabledMessage` (no
  // project) or nothing (brief load), so this never double-messages or fires prematurely.
  const isTextsListEmpty =
    top.length === 0 && bottom.length === 0 && installingResourceNames.length === 0;

  const getResourcesLabel = localize(
    localizedStrings,
    RESOURCE_COLLECTION_OPTIONS_KEYS.getResources,
  );
  // The Get Resources button label ends with an ellipsis (the dialog-opening affordance
  // convention); drop it when the label is embedded mid-sentence in the empty prompt so it reads
  // cleanly. Interpolating the label (rather than hardcoding it in the message) keeps the prompt in
  // sync if the button is ever renamed. The trailing-ellipsis regex tolerates the forms a localizer
  // might use: one or two `…` characters (CJK convention doubles it), the three-ASCII-dot fallback
  // `...`, and any trailing whitespace after it (including the full-width space `\s` matches).
  const getResourcesLabelInProse = getResourcesLabel.replace(/(?:…{1,2}|\.{3})\s*$/u, '');

  const handleViewModeChange = (value: string) => {
    // Radix single-toggle emits '' when the active item is clicked again; ignore that (a view mode
    // is always selected) and any unexpected value.
    if (isResourceCollectionViewMode(value)) onViewModeChange(value);
  };

  const renderRow = (row: ViewOptionsTextEntry) => {
    const { id, name } = row.reference;
    const { longName } = row;
    // Composed in JS (not a raw JSX text node) so the em-dash separator does not trip
    // no-hardcoded-jsx-strings.
    const fullLabel = longName ? `${name} — ${longName}` : name;
    return (
      <div key={id} className="tw:group tw:flex tw:min-w-0 tw:items-center tw:gap-2 tw:py-1">
        <Label className="tw:flex tw:min-w-0 tw:flex-1 tw:items-center tw:gap-2 tw:font-normal">
          <Checkbox
            checked={row.checked}
            disabled={disabled}
            onCheckedChange={(checked) => onCheckedChange(id, checked === true)}
          />
          {/* `title` carries the untruncated label so long DBL names stay readable in the narrow
              panel (native tooltip on overflow). `dir="auto"` per name span keeps each name's
              direction (and the separator) correct for RTL resources. */}
          {longName ? (
            <span className="tw:flex tw:min-w-0 tw:flex-1 tw:items-baseline" title={fullLabel}>
              {/* Short name never truncates; only the long name ellipsizes when the row is tight.
                  `dir="auto"` per name span keeps each name's direction (and the separator) correct
                  for RTL resources. */}
              <span className="tw:shrink-0" dir="auto">
                {name}
              </span>
              {/* An em dash rather than `PROJECT_NAME_SEPARATOR`: this is a long-name SLOT the row
                  renders after the short name, not a joined label, and the panel's own typography
                  uses the em dash. The order still leads with the short name. */}
              <span
                className="tw:min-w-0 tw:flex-1 tw:truncate"
                dir="auto"
              >{` — ${longName}`}</span>
            </span>
          ) : (
            <span className="tw:min-w-0 tw:flex-1 tw:truncate" title={name} dir="auto">
              {name}
            </span>
          )}
        </Label>
        {row.isUserRemovable && (
          <Button
            variant="ghost"
            size="icon-sm"
            disabled={disabled}
            aria-label={formatReplacementString(
              localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.removeFromList),
              { resourceName: name },
            )}
            aria-describedby={hasRemoveHint ? removeHintId : undefined}
            className="tw:shrink-0 tw:opacity-0 tw:transition-opacity tw:group-hover:opacity-100 tw:focus-visible:opacity-100"
            onClick={() => onRemoveFromList(id)}
          >
            <X className="tw:h-4 tw:w-4" />
          </Button>
        )}
        {/* Lock marks the team's rows (the top section), which can't be removed.
            Gated on isAdminLocked, NOT !isUserRemovable: downloaded rows in the bottom section
            are also non-removable but are not the team's, so they get no lock. `role="img"`
            makes the label reliably announced even while the icon is visually hover-revealed. */}
        {isGrouped && row.isAdminLocked && (
          <span
            role="img"
            aria-label={localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.teamSharedLock)}
            className="tw:flex tw:h-8 tw:w-8 tw:items-center tw:justify-center tw:text-muted-foreground tw:opacity-0 tw:transition-opacity tw:group-hover:opacity-100 tw:group-focus-within:opacity-100"
          >
            <Lock className="tw:h-4 tw:w-4" />
          </span>
        )}
      </div>
    );
  };

  // `bottom` is not only what the user picked: it can also hold downloaded resources nobody listed,
  // hence "User resources" rather than a word claiming a choice.
  const userRows = (
    <>
      {bottom.map(renderRow)}
      {installingResourceNames.map((name) => (
        <div
          key={`installing-${name}`}
          className="tw:flex tw:items-center tw:py-1 tw:text-sm tw:text-muted-foreground tw:italic"
        >
          {formatReplacementString(
            localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.installing),
            { resourceName: name },
          )}
        </div>
      ))}
    </>
  );

  // A plain element rather than `Label`, which renders a `<label>` with no control to label. Regular
  // weight, against the section headings' semibold, so the groups read as part of TEXTS.
  const renderGroup = (
    headingId: string,
    headingKey: ResourceCollectionOptionsStringKey,
    rows: ReactNode,
    className?: string,
  ) => (
    <div
      role="group"
      aria-labelledby={headingId}
      className={cn('tw:flex tw:flex-col tw:gap-1', className)}
    >
      <div id={headingId} className="tw:text-xs tw:text-muted-foreground">
        {localize(localizedStrings, headingKey)}
      </div>
      {rows}
    </div>
  );

  return (
    <div className="tw:flex tw:w-64 tw:flex-col tw:gap-4">
      <section className="tw:flex tw:flex-col tw:gap-2">
        <Label className="tw:text-xs tw:font-semibold tw:text-muted-foreground">
          {localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.viewHeader)}
        </Label>
        <div className="tw:flex tw:items-center tw:gap-2">
          <ToggleGroup
            type="single"
            variant="outline"
            value={viewMode}
            onValueChange={handleViewModeChange}
          >
            <ToggleGroupItem value="verse">
              {localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.verse)}
            </ToggleGroupItem>
            <ToggleGroupItem value="chapter" disabled={!isChapterEnabled}>
              {localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.chapter)}
            </ToggleGroupItem>
            {/* The verse-aligned grid. Labeled "Grid" for the user; the value is `aligned` because
                the surface as a whole is the Scripture Text Grid. */}
            <ToggleGroupItem value="aligned">
              {localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.grid)}
            </ToggleGroupItem>
          </ToggleGroup>
          {!isChapterEnabled && (
            <span className="tw:text-xs tw:text-muted-foreground tw:italic">
              {localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.chapterNotYetAvailable)}
            </span>
          )}
        </div>
      </section>

      <section className="tw:flex tw:flex-col tw:gap-1">
        <Label className="tw:text-xs tw:font-semibold tw:text-muted-foreground">
          {localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.textsHeader)}
        </Label>
        {disabled && disabledMessage && (
          <EmptyState className="tw:py-1 tw:italic" message={disabledMessage} />
        )}
        {!disabled && isTextsListEmpty && (
          <EmptyState
            className="tw:py-1 tw:italic"
            message={formatReplacementString(
              localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.emptyTexts),
              { getResourcesLabel: getResourcesLabelInProse },
            )}
          />
        )}
        {/* Ungrouped, or with no team rows, the list is one unlabeled run. */}
        {isGrouped && hasTeamRows ? (
          <>
            {renderGroup(
              teamHeadingId,
              RESOURCE_COLLECTION_OPTIONS_KEYS.teamResourcesHeader,
              top.map(renderRow),
              'tw:mt-1',
            )}
            {hasUserRows &&
              renderGroup(
                userHeadingId,
                RESOURCE_COLLECTION_OPTIONS_KEYS.userResourcesHeader,
                userRows,
                'tw:mt-2',
              )}
          </>
        ) : (
          <>
            {top.map(renderRow)}
            {userRows}
          </>
        )}
        {hasRemoveHint && (
          <p id={removeHintId} className="tw:pt-1 tw:text-xs tw:text-muted-foreground">
            {localize(localizedStrings, RESOURCE_COLLECTION_OPTIONS_KEYS.removeFromListHint)}
          </p>
        )}
      </section>

      {/* Deliberately not gated on `disabled` — see the prop's docs. */}
      <Button variant="outline" onClick={() => onGetResources()}>
        {getResourcesLabel}
      </Button>
    </div>
  );
}
